import{_ as o,b as d,c as l,d as c,t as u,C as i,u as v}from"./index-I5uTs6b4.js";const n={class:"level-page"},b={class:"level-content"},q={class:"level-title"},p={__name:"Level35",props:{id:{type:String,required:!0}},setup(a){const e=v();function s(){sessionStorage.setItem("skipIntro","1"),e.push("/")}return(r,t)=>(d(),l("div",n,[c("button",{class:"back-btn",onClick:s},"← Back to Index"),c("div",b,[c("h1",q,"SI-"+u(a.id),1),t[0]||(t[0]=i('<p class="level-name" data-v-cb1cc89e>&quot;possibility&quot;</p><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>生存难度：2（宜居）</h2><div class="difficulty" data-v-cb1cc89e><ul class="class-list" data-v-cb1cc89e><li data-v-cb1cc89e><span class="class-bullet unsafe" data-v-cb1cc89e></span> 不安全</li><li data-v-cb1cc89e><span class="class-bullet stable" data-v-cb1cc89e></span> 稳定</li><li data-v-cb1cc89e><span class="class-bullet entity" data-v-cb1cc89e></span> ？？？</li></ul></div></div><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>层级概述</h2><p data-v-cb1cc89e>Level SI-35 &quot;possibility&quot;，其已探明区域为面积 335 平方千米的一块陆地，四周为海洋。该陆地几乎被平原与河流填充，其土壤极其适合种植作物。这块陆地上有着 3-4 个大城市以及若干小聚落，M.E.G、B.N.T.G、BAUT 等组织皆与这里的城市有所合作，TMS 也在此处常驻几支小队以应对特殊实体&quot;灾&quot;。物资来源有耕作、交易以及通过特殊实体&quot;盒&quot;获得。</p></div><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>Phenomenon —— &quot;盒&quot;化</h2><p data-v-cb1cc89e>在 Level SI-35 中，封闭的容器有时会出现特殊的变化，称之为&quot;盒&quot;化。受影响容器上会出现一种类似荆棘的纹路，在 30 分钟内会慢慢变得明显，最后该纹路将会发出紫光，此时该容器会被转化为特殊实体<strong data-v-cb1cc89e>&quot;盒&quot;</strong>。</p></div><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>特殊实体 &quot;盒&quot;</h2><p data-v-cb1cc89e>表现为周身有着发着紫光荆棘纹路的密封容器。被流浪者打开时，内容物将会是完全随机的：可能蹦出几千瓶杏仁水、几乎无限的皇家口粮、各种武器、各种物资；也有可能从中切入实体（但不会出现比&quot;灾&quot;更危险的实体）；甚至有可能出现切入其他层级的通道。特殊实体&quot;盒&quot;不可被带出 Level SI-35。</p></div><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>特殊实体 &quot;灾&quot;</h2><p data-v-cb1cc89e>仅会在&quot;盒&quot;中出现的实体。&quot;灾&quot;在同一时间只能出现一个。在外形上表现为一只西方龙，站立时约 10 米高，龙尾约有 3 米长。破坏力强大，具有一定程度的智慧，且每次现身时会展现不同的能力（身体素质强化、高密度能量束、快速自愈、短距离空间转移、使役死灵士兵、皮肤酸液、传送吞入者等）。每次出现只会拥有一种特性。由于&quot;灾&quot;存在时&quot;盒&quot;不会再出现新的&quot;灾&quot;，此时为囤积物资的好时机。</p></div><div class="section" data-v-cb1cc89e><h2 data-v-cb1cc89e>切入和切出</h2><h3 class="sub-heading" data-v-cb1cc89e>切入</h3><p data-v-cb1cc89e>保持着好奇心不目视其内容物地打开一个容器并摸索就有可能切入 Level SI-35。</p><h3 class="sub-heading" data-v-cb1cc89e>切出</h3><p data-v-cb1cc89e>通过特殊实体&quot;盒&quot;或被特殊形态的&quot;灾&quot;吞入腹中可以切出。</p></div>',7))])]))}},_=o(p,[["__scopeId","data-v-cb1cc89e"]]);export{_ as default};
